from typing import List

def maximumScore(nums: List[int], multipliers: List[int]) -> int:
    n, m = len(nums), len(multipliers)

    # Memoization cache
    memo = {}

    def dfs(left: int, right: int, op: int) -> int:
        if op == m:
            return 0

        if (left, right, op) in memo:
            return memo[(left, right, op)]

        # Choose from the left side
        score_left = nums[left] * multipliers[op] + dfs(left + 1, right, op + 1)
        # Choose from the right side
        score_right = nums[right] * multipliers[op] + dfs(left, right - 1, op + 1)

        result = max(score_left, score_right)
        memo[(left, right, op)] = result
        return result

    return dfs(0, n - 1, 0)

